from django.views import View
from django.http import JsonResponse, HttpResponseForbidden, HttpResponseNotFound
from .models import TranslatedPolicyAuditLog

class PolicyTranslationHistoryView(View):
    def get(self, request, policy_id):
        if not request.user.is_authenticated:
            return HttpResponseForbidden("Login required")

        lang = request.GET.get('lang', 'es')
        # Ensure policy belongs to the authenticated user's organization
        history = TranslatedPolicyAuditLog.objects.filter(
            policy_id=policy_id,
            policy__organization=request.user.organization,
            translated_field=f"compliance_clause_{lang}"
        ).order_by('-modified_at').values('revision_id', 'previous_text', 'new_text', 'modified_by_id')

        if not history.exists():
            return HttpResponseNotFound("No audit history found")

        return JsonResponse({"policy_id": policy_id, "language": lang, "revisions": list(history)})
